"""Independent oracles: these assertions are not generated by the compiler."""

from __future__ import annotations

import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

from compiler import compile_ast
from epistula.ast_nodes import BinaryExprNode, IntegerLiteralNode
from epistula.checks import OverflowChecker
from epistula.errors import CompilationError
from epistula.lexer import Lexer
from epistula.parser import Parser
from epistula.tokens import TokenKind


ROOT = Path(__file__).resolve().parent.parent


def parse(source: str):
    return Parser(Lexer(source.encode("utf-8")).scan()).parse_program()


def check(source: str):
    program = parse(source)
    OverflowChecker().check(program)
    return program


class LexerTests(unittest.TestCase):
    def test_every_token_has_exact_byte_position_and_text(self):
        tokens = Lexer("Count ⬅ XV.\n".encode()).scan()
        self.assertEqual(
            [(t.kind, t.text, t.line, t.column) for t in tokens],
            [(TokenKind.IDENTIFIER, "Count", 1, 1),
             (TokenKind.ASSIGN, "⬅", 1, 7),
             (TokenKind.ROMAN_INTEGER, "XV", 1, 11),
             (TokenKind.DOT, ".", 1, 13),
             (TokenKind.NEWLINE, "\n", 1, 14),
             (TokenKind.EOF, "", 2, 1)],
        )

    def test_line_endings_and_line_comments(self):
        for ending in ("\n", "\r\n", "\r"):
            with self.subTest(ending=repr(ending)):
                program = parse(f"N.B. comment{ending}Scribe X.{ending}")
                self.assertEqual(program.statements[0].line, 2)
                self.assertEqual(program.statements[0].column, 1)

    def test_multiline_comment_updates_position_without_layout_token(self):
        tokens = Lexer(b"(N.B. one\r\ntwo)Scribe X.\n").scan()
        self.assertEqual((tokens[0].kind, tokens[0].line, tokens[0].column),
                         (TokenKind.PRINT, 2, 5))
        self.assertEqual(sum(t.kind == TokenKind.NEWLINE for t in tokens), 1)

    def test_invalid_utf8_in_comment_is_not_ignored(self):
        with self.assertRaises(CompilationError) as caught:
            Lexer(b"N.B. \xff\n").scan()
        self.assertEqual((caught.exception.line, caught.exception.column), (1, 6))

    def test_decimal_subtraction_without_spaces(self):
        expr = parse("Scribe 10-2.\n").statements[0].arguments[0].value
        self.assertIsInstance(expr, BinaryExprNode)
        self.assertEqual(expr.operator, "-")

    def test_all_canonical_roman_literals(self):
        for value in range(1, 4000):
            token = Lexer(Lexer.roman_text(value).encode()).scan()[0]
            self.assertEqual(token.kind, TokenKind.ROMAN_INTEGER)
            self.assertEqual(Lexer.roman_value(token.text), value)

    def test_noncanonical_roman_literals(self):
        for text in ("IIII", "IC", "VX", "MMMM", "IIV", "DD", "XM"):
            with self.subTest(text=text), self.assertRaises(CompilationError):
                Lexer(text.encode()).scan()

    def test_long_leading_zeros_do_not_hit_python_integer_limits(self):
        expr = parse("Scribe " + "0" * 5000 + "15.\n").statements[0].arguments[0].value
        self.assertIsInstance(expr, IntegerLiteralNode)
        self.assertEqual(expr.value, 15)

    def test_long_number_is_a_compilation_error(self):
        with self.assertRaises(CompilationError):
            parse("Scribe " + "9" * 5000 + ".\n")

    def test_invalid_identifier_initial_characters(self):
        for name in ("_name", "123name", "provisum", "X"):
            with self.subTest(name=name), self.assertRaises(CompilationError):
                parse(f"variabilis 32bitInt {name} <- I.\n")


class ParserTests(unittest.TestCase):
    def test_precedence_has_independent_tree_oracle(self):
        expr = parse("Scribe 2 adde 3 * 4.\n").statements[0].arguments[0].value
        self.assertEqual(expr.operator, "adde")
        self.assertEqual(expr.left.value, 2)
        self.assertEqual(expr.right.operator, "*")
        self.assertEqual((expr.right.left.value, expr.right.right.value), (3, 4))

    def test_power_is_left_associative_as_requested(self):
        expr = parse("Scribe 2 ^ 3 exponens 2.\n").statements[0].arguments[0].value
        self.assertEqual(expr.operator, "exponens")
        self.assertEqual(expr.left.operator, "^")
        self.assertEqual(expr.right.value, 2)

    def test_sign_and_power(self):
        expr = parse("Scribe -2^2.\n").statements[0].arguments[0].value
        self.assertEqual(expr.operator, "-")
        self.assertEqual(expr.operand.operator, "^")
        expr = parse("Scribe 2^-2.\n").statements[0].arguments[0].value
        self.assertEqual(expr.right.operator, "-")

    def test_empty_else_is_forbidden(self):
        with self.assertRaises(CompilationError) as caught:
            parse("provisum Veritas <<\nScribe I;\n>>,\naliter <<\n>>.\n")
        self.assertEqual(caught.exception.message, "Clausula vacua esse non potest.")

    def test_parentheses_cannot_bypass_quotation_marker(self):
        with self.assertRaises(CompilationError):
            parse('Scribe (("text")).\n')

    def test_strings_in_comparisons_are_not_printed_literals(self):
        parse('Scribe "text" idem Legere.\n')
        parse('Scribe Legere idem "text".\n')

    def test_aliases_have_same_mutability(self):
        program = parse("immutabilis 32bitInt First <- I.\n"
                        "inaeternum 32bitInt Second <- II.\n")
        self.assertFalse(program.statements[0].mutable)
        self.assertFalse(program.statements[1].mutable)

    def test_string_escape_and_nihil_values(self):
        program = parse('Scribe - "a/lineab//c", - "nihil".\n')
        values = [arg.value.value for arg in program.statements[0].arguments]
        self.assertEqual(values, ["a\nb/c", ""])

    def test_error_points_to_second_illegal_else_comma(self):
        source = ("provisum Veritas <<\nScribe I;\n>>,\n"
                  "aliter <<\nScribe II;\n>>,\naliter <<\nScribe III;\n>>.\n")
        with self.assertRaises(CompilationError) as caught:
            parse(source)
        self.assertEqual((caught.exception.line, caught.exception.column), (6, 3))


class OverflowTests(unittest.TestCase):
    def test_exact_signed_bounds(self):
        for type_name, bits in (("32bitInt", 32), ("64bitInt", 64)):
            for value in (-(2 ** (bits - 1)), 2 ** (bits - 1) - 1):
                with self.subTest(type=type_name, value=value):
                    check(f"variabilis {type_name} Bound <- {value}.\n")
            for value in (-(2 ** (bits - 1)) - 1, 2 ** (bits - 1)):
                with self.subTest(type=type_name, value=value):
                    with self.assertRaises(CompilationError):
                        check(f"variabilis {type_name} Bound <- {value}.\n")

    def test_large_exponents_cannot_bypass_overflow(self):
        with self.assertRaises(CompilationError):
            check("variabilis 64bitInt Result <- 2 ^ 10001.\n")
        with self.assertRaises(CompilationError):
            check("variabilis 64bitInt Result <- 2 ^ 9223372036854775807.\n")
        check("variabilis 32bitInt Result <- 1 ^ 2147483647.\n")

    def test_intermediate_overflow(self):
        with self.assertRaises(CompilationError):
            check("variabilis 32bitInt Result <- 2147483647 + 1 - 1.\n")

    def test_assignment_overflow(self):
        with self.assertRaises(CompilationError):
            check("variabilis 32bitInt Count <- 0.\nCount <- 2147483648.\n")

    def test_branch_shadowing_does_not_leak(self):
        source = ("variabilis 32bitInt Count <- I.\n"
                  "provisum Veritas <<\n"
                  "variabilis 64bitInt Count <- I;\n"
                  ">>,\naliter <<\nCount <- 2147483648;\n>>.\n")
        with self.assertRaises(CompilationError):
            check(source)

    def test_local_type_does_not_replace_enclosing_type(self):
        check("variabilis 64bitInt Count <- I.\n"
              "provisum Veritas <<\n"
              "variabilis 32bitInt Count <- I;\n>>.\n"
              "Count <- 2147483648.\n")

    def test_division_and_remainder_agree(self):
        checker = OverflowChecker()
        for source, expected in (("-7 / 3", -2), ("-7 % 3", -1),
                                 ("7 / -3", -2), ("7 % -3", 1)):
            expr = parse(f"Scribe {source}.\n").statements[0].arguments[0].value
            self.assertEqual(checker._constant_integer(expr, "32bitInt"), expected)

    def test_deferred_semantics_are_not_silently_implemented(self):
        # Stage 1 parses structure, not name resolution, immutability or bool
        # type inference. These deliberately parse for the next project stage.
        check("Unknown <- Other.\n")
        check("provisum Unknown <<\nScribe I;\n>>.\n")


class CLITests(unittest.TestCase):
    def run_cli(self, source: bytes):
        with tempfile.TemporaryDirectory() as temporary:
            path = Path(temporary) / "input.em"
            path.write_bytes(source)
            environment = os.environ.copy()
            environment["PYTHONIOENCODING"] = "ascii"
            return subprocess.run(
                [sys.executable, str(ROOT / "compiler.py"), "--ast", str(path)],
                capture_output=True, timeout=10, env=environment,
            )

    def test_invalid_input_has_one_error_and_no_stdout(self):
        completed = self.run_cli(b"provisum Veritas <<\n>>.\n")
        self.assertNotEqual(completed.returncode, 0)
        self.assertEqual(completed.stdout, b"")
        self.assertEqual(completed.stderr,
                         b"compilation error: line 2:1: Clausula vacua esse non potest.\n")

    def test_utf8_output_under_ascii_locale(self):
        completed = self.run_cli('Count ⬅ XV.\n'.encode())
        self.assertEqual(completed.returncode, 0)
        self.assertEqual(completed.stderr, b"")
        self.assertIn('operator="⬅"'.encode(), completed.stdout)

    def test_long_number_has_no_traceback(self):
        completed = self.run_cli(b"Scribe " + b"9" * 5000 + b".\n")
        self.assertNotEqual(completed.returncode, 0)
        self.assertEqual(completed.stdout, b"")
        self.assertEqual(completed.stderr.count(b"\n"), 1)
        self.assertNotIn(b"Traceback", completed.stderr)

    def test_deep_input_has_no_traceback(self):
        completed = self.run_cli(b"Scribe " + b"(" * 1500 + b"1" + b")" * 1500 + b".\n")
        self.assertNotEqual(completed.returncode, 0)
        self.assertEqual(completed.stdout, b"")
        self.assertEqual(completed.stderr.count(b"\n"), 1)
        self.assertNotIn(b"Traceback", completed.stderr)

    def test_missing_file_is_formatted(self):
        with tempfile.TemporaryDirectory() as temporary:
            with self.assertRaises(CompilationError) as caught:
                compile_ast(Path(temporary) / "missing.em")
            self.assertEqual(caught.exception.formatted(),
                             "compilation error: line 1:1: Fasciculus legi non potest.")


if __name__ == "__main__":
    unittest.main()
